// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
dimensions [0 2 -2 0 0 0 0];
internalField uniform 0.0;
boundaryField
{
inlet
{
type fixedValue;
value uniform 1.0e-7;
}
outlet
{
type inletOutlet;
inletValue uniform 1.0e-7;
value uniform 1.0e-7;
}
walls
{
type zeroGradient;
}
}
// ************************************************************************* //
0.orig/Theta 设置 Theta 的内部初值和边界条件。dimensions 为 [0 2 -2 0 0 0 0]，单位为 m²/s²。internalField 为 uniform 0.0；uniform 表示所有内部单元采用相同初值。
inlet 采用 fixedValue，边界始终采用给定的 value。参数为 value uniform 1.0e-7。
outlet 采用 inletOutlet，出流时外推，回流时采用 inletValue。参数为 inletValue uniform 1.0e-7，value uniform 1.0e-7。
