#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
mkdir -p constant/triSurface
# Copy bullet surface from resources directory
cp -f \
"$FOAM_TUTORIALS"/resources/geometry/bullet.stl.gz \
constant/triSurface/
# Generate the base block mesh
runApplication blockMesh
# Generate the snappy mesh
runApplication snappyHexMesh -overwrite
restore0Dir
# Initialise with potentialFoam solution
runApplication potentialFoam -pName p_rgh -writephi
# Run the solver
runApplication $(getApplication)
#------------------------------------------------------------------------------
cd 切换当前工作目录。
mkdir 创建一个或多个目录。
cp 复制文件或目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
snappyHexMesh 细化背景网格，贴合几何表面，并按设置生成边界层。结果覆盖当前网格。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
potentialFoam 求解势流方程，常用于初始化速度与通量。
从 system/controlDict 的 application 读取求解器名称，运行后将日志保存在算例目录。
